package com.muthumol.player.dummy;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Bounded container metadata reads; mdat/Cluster payloads are skipped by declared length. */
final class ChapterReader {
 interface Source{byte[] read(long offset,int length)throws IOException;long size();}
 static final class Chapter{final long time;final String title;Chapter(long t,String s){time=t;title=s;}}
 static final int LIMIT=8*1024*1024;
 static long uint(byte[] b,int at,int count)throws IOException{if(at<0||count<1||count>8||at+count>b.length)throw new IOException("Invalid chapter integer");long n=0;for(int i=0;i<count;i++){if(n>(Long.MAX_VALUE>>>8))throw new IOException("Chapter integer overflow");n=(n<<8)|(b[at+i]&255);}return n;}
 static List<Chapter> read(Source source)throws IOException {List<Chapter> out=new ArrayList<>();if(source.size()<8)return out;byte[] first=source.read(0,(int)Math.min(16,source.size()));if((first[0]&255)==0x1a&&(first[1]&255)==0x45){long pos=0,segment=-1;for(int n=0;n<1000&&pos+2<source.size();n++){byte[] header=source.read(pos,(int)Math.min(16,source.size()-pos));Element e=element(header,0,header.length);long content=pos+e.header,size=e.unknown?source.size()-content:e.size;if(e.id==0x18538067L){segment=content;pos=content;continue;}if(e.id==0x1043a770L&&size<=LIMIT){mkv(source.read(content,(int)size),0,(int)size,out,0);break;}if(e.id==0x1f43b675L)break;if(size<0||size>source.size()-content)break;pos=content+size;}}
 else{long pos=0;for(int count=0;count<10000&&pos+8<=source.size();count++){byte[] header=source.read(pos,(int)Math.min(16,source.size()-pos));long size=uint(header,0,4);int h=8;if(size==1){if(header.length<16)break;size=uint(header,8,8);h=16;}else if(size==0)size=source.size()-pos;if(size<h||size>source.size()-pos)break;String type=new String(header,4,4,StandardCharsets.US_ASCII);if(type.equals("moov")&&size-h<=LIMIT){byte[] metadata=source.read(pos+h,(int)(size-h));mp4(metadata,0,metadata.length,out,0);break;}pos+=size;}}
 out.sort(Comparator.comparingLong(x->x.time));List<Chapter> unique=new ArrayList<>();long last=-1;for(Chapter c:out)if(c.time>=0&&c.time!=last){unique.add(c);last=c.time;if(unique.size()==2000)break;}return unique;}
 static void mp4(byte[] data,int from,int end,List<Chapter> out,int depth)throws IOException{if(depth>12)return;for(int at=from;at+8<=end;){long size=uint(data,at,4);int h=8;if(size==1){size=uint(data,at+8,8);h=16;}if(size<h||size>end-at)return;int to=at+(int)size;String type=new String(data,at+4,4,StandardCharsets.US_ASCII);if(type.equals("moov")||type.equals("udta"))mp4(data,at+h,to,out,depth+1);if(type.equals("chpl")){int cursor=at+h+8;if(cursor>=to)return;int entries=data[cursor++]&255;for(int i=0;i<entries&&cursor+9<=to;i++){long ms=uint(data,cursor,8)/10000;cursor+=8;int len=data[cursor++]&255;if(cursor+len>to)return;String title=new String(data,cursor,len,StandardCharsets.UTF_8);cursor+=len;out.add(new Chapter(ms,title.isEmpty()?"Chapter "+(out.size()+1):title));}}at=to;}}
 static final class Element{long id,size;int header;boolean unknown;}
 static Element element(byte[] data,int at,int end)throws IOException{if(at>=end)throw new IOException("Truncated EBML");int idBytes=vintBytes(data[at]);if(idBytes>4||at+idBytes>=end)throw new IOException("Invalid EBML id");Element e=new Element();e.id=uint(data,at,idBytes);int p=at+idBytes,n=vintBytes(data[p]);if(p+n>end)throw new IOException("Truncated EBML size");long size=data[p]&((1<<(8-n))-1);for(int i=1;i<n;i++)size=(size<<8)|(data[p+i]&255);e.size=size;e.header=idBytes+n;e.unknown=size==((1L<<(7*n))-1);return e;}
 static int vintBytes(byte first)throws IOException{int b=first&255;for(int n=1;n<=8;n++)if((b&(1<<(8-n)))!=0)return n;throw new IOException("Invalid EBML varint");}
 static void mkv(byte[] data,int from,int end,List<Chapter> out,int depth)throws IOException{if(depth>16)return;for(int at=from;at<end;){Element e=element(data,at,end);int start=at+e.header;if(e.unknown||e.size>end-start)return;int next=start+(int)e.size;if(e.id==0xb6){long time=-1;String title="";for(int p=start;p<next;){Element child=element(data,p,next);int value=p+child.header;if(child.unknown||child.size>next-value)break;int stop=value+(int)child.size;if(child.id==0x91)time=uint(data,value,(int)child.size)/1000000;if(child.id==0x80){for(int q=value;q<stop;){Element text=element(data,q,stop);int v=q+text.header;if(text.unknown||text.size>stop-v)break;if(text.id==0x85)title=new String(data,v,(int)text.size,StandardCharsets.UTF_8);q=v+(int)text.size;}}p=stop;}if(time>=0)out.add(new Chapter(time,title.isEmpty()?"Chapter "+(out.size()+1):title));mkv(data,start,next,out,depth+1);}else if(e.id==0x45b9||e.id==0x1043a770)mkv(data,start,next,out,depth+1);at=next;}}
}
